try (var s = Files.walk(root)) {
    List<Path> all = s.sorted(Comparator.reverseOrder()).toList();
    for (Path p : all) Files.delete(p);
}

// reverseOrder 가 핵심이다 — 경로를 거꾸로 정렬하면 깊은 것이 먼저 온다.
// fa/a/b/c 가 fa/a/b 보다 앞에 오므로 DirectoryNotEmptyException 이 안 난다.
// walk 는 Stream 이라 try-with-resources 가 필요하다(4.3절).
